`timescale 1ns / 1ps
// Directed BUFGCTRL experiments: each instance settles, then one control
// (a select, an enable, with or without IGNORE) changes and changes back,
// each time at a chosen phase of the two clocks and half a nanosecond away
// from any edge; every output change is printed with its quarter
// nanosecond.
module tb;
  reg i0 = 1'b0, i1 = 1'b0;
  always #5 i0 = ~i0;
  initial begin
    #1.5;
    forever #7 i1 = ~i1;
